import pytest

from harness import EMERGENCY_SCRIPT


@pytest.mark.criterion("FERN-4/AC-1")
@pytest.mark.parametrize(
    "said",
    [
        "I have chest pain.",
        "My husband is having trouble breathing.",
        "I think my mother is having a stroke.",
        "This is an emergency.",
    ],
)
def test_emergency_phrases_get_the_script_and_a_flag(call, said):
    reply = call.say(said)

    assert reply.text == EMERGENCY_SCRIPT
    assert "emergency" in call.record()["flags"]

import pytest

from harness import EMERGENCY_SCRIPT


@pytest.mark.criterion("FERN-4/AC-2")
def test_emergency_script_plays_with_the_model_down(start_call):
    for said in ["I have chest pain.", "I can't breathe."]:
        call = start_call(model_available=False)
        assert call.say(said).text == EMERGENCY_SCRIPT
